namespace Library.Authors
{
    #region Lookup
    public class AuthorLookupService : IAuthorLookup
    {
        readonly IAuthorStore store;
        public Author Find(string id)
        {
            if (id == null) throw new ArgumentException("id");
            Author author = store.Get(id);
            if (author == null) throw new AuthorNotFoundException(id);
            return author;
        }
    }
    #endregion
